int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    git_index_entry *entry = NULL;
    size_t size = 0;

    if (!buffer || buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    entry = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));
    size = sizeof(git_index_entry);

    if (entry->flags & GIT_INDEX_ENTRY_COMPRESSED) {
        char *path;
        size_t path_len = strlen(last) + strlen(entry->path) + 1;

        path = (char *)malloc(path_len);
        if (!path) {
            free(entry);
            return -1;
        }

        snprintf(path, path_len, "%s%s", last, entry->path);
        free(entry->path);
        entry->path = path;
    }

    if (entry->mode == 0 || entry->file_size == 0) {
        free(entry->path);
        free(entry);
        return -1;
    }

    *out = entry;
    *out_size = size;
    return 0;
}

