    return 0;
}

int git_index_entry_read(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    git_index_entry *entry = (git_index_entry *)malloc(buffer_size);
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, buffer_size);

    if (entry->flags & GIT_INDEXENTRY_UNMERGED) {
        free(entry);
        return -1;
    }

    if (entry->flags & GIT_INDEXENTRY_HASH_VALID) {
        if (!git_hash_is_valid(&entry->oid)) {
            free(entry);
            return -1;
        }
    }

    if (last && (entry->flags & GIT_INDEXENTRY_CASE_MODIFIED)) {
        size_t last_len = strlen(last);
        entry->path = (char *)malloc(last_len + strlen(entry->path) + 2);
        if (!entry->path) {
            free(entry);
            return -1;
        }
        snprintf(entry->path, last_len + strlen(entry->path) + 2, "%s/%s", last, entry->path);
    }

    *out = entry;
    *out_size = buffer_size;

    return 0;
}

int git_index_entry_read(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    if (!buffer || buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    git_index_entry *entry = (git_index_entry *)malloc(buffer_size);
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, buffer_size);

    if (entry->flags & GIT_INDEX_ENTRY_VALID) {
        if (entry->flags & GIT_INDEX_ENTRY_COMPRESSED) {
            size_t path_len = strlen(last) + 1 + strlen(entry->path);
            char *full_path = (char *)malloc(path_len);
            if (!full_path) {
                free(entry);
                return -1;
            }

            snprintf(full_path, path_len, "%s/%s", last, entry->path);
            free(entry->path);
            entry->path = full_path;
        }
    } else {
        free(entry);
        return -1;
    }

    *out = entry;
    *out_size = buffer_size;
    return 0;
}

int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    if (!buffer || buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    git_index_entry *entry = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));
    *out_size = sizeof(git_index_entry);

    if (entry->flags & GIT_INDEX_ENTRY_COMPRESSED) {
        size_t last_len = strlen(last);
        entry->path = (char *)malloc(last_len + strlen(entry->path) + 1);
        if (!entry->path) {
            free(entry);
            return -1;
        }
        strcpy(entry->path, last);
        strcat(entry->path, "/");
        strcat(entry->path, entry->path + strlen(last));
    }

    *out = entry;
    return 0;
}
